      // Bound to the decision by id; consumed when a turn reaches it (an unresolved steering conflict: at the next
      // turn's start). An id no turn asked about is simply never consumed.
      this.app.getAgent().setOperatorAnswers(new Map([[command.question, command.option]]));
      this.emit({ type: "notice", text: `Answer recorded for question ${command.question}: ${command.option}. It applies when the next turn reaches that decision.` });
      return;
    case "checkpoint.choice":
      this.resolveCheckpointChoice(command.id, command.choice);
      return;
    case "slash":
      this.slash(command.id, command.command, command.args);
      return;
    case "tool.detail":
    case "receipt":
      try {
        if (command.type === "tool.detail") this.toolDetail(command.id, command.evidence);
        else this.emit({ type: "receipt", id: command.id, sections: this.receipt() });
      } catch (err) {
        const message = errorText(err);
        this.emit({ type: "error", id: command.id, code: "INTERNAL", message });
      }
      return;
    case "models.list":
      if (this.app.getAgent().getApprovalMode() === "read-only") {
        this.emit({ type: "error", id: command.id, code: "BUSY", message: "Provider discovery is disabled while the session is in read-only mode." });
        return;
      }
      void this.modelsList(command.id);
      return;
    case "model.select":
      if (this.app.getAgent().getApprovalMode() === "read-only") {
        this.emit({ type: "error", id: command.id, code: "BUSY", message: "Model changes are disabled while the session is in read-only mode." });
        return;
      }
      this.modelSelect(command.id, command.provider, command.model);
      return;
    case "provider.connect":
      if (this.app.getAgent().getApprovalMode() === "read-only") {
        this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: false, message: "Provider connections are disabled while the session is in read-only mode." });
        return;
      }
      void this.providerConnect(command.id, command.provider, command.method, command.key, command.endpoint);
      return;
    case "provider.cancel":
      this.modelLists.get(command.id)?.abort();
      this.signIns.get(command.id)?.cancel();
      this.signIns.delete(command.id);
      cancelLocalEndpointSetup(command.id);
      return;
    case "provider.local-cancel":
      clearLocalEndpointSetup(command.id);
      return;
    case "provider.disconnect": {
      if (this.app.getAgent().getApprovalMode() === "read-only") {
        this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: false, message: "Provider changes are disabled while the session is in read-only mode." });
        return;
      }
      const r = disconnect(command.provider);
      this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: r.ok, message: r.message });
      return;
    }
    case "shutdown":
      await this.shutdown();
      return;
  }
}

/**
 * Negotiation for this connection. It only records connection state, so it is answered at any time, a running turn
 * included. Rule: a connection negotiates once. After an `initialized` answer every later `initialize` is refused
 * with BAD_REQUEST, because a version or an experimental set that changed mid-connection would leave both sides
 * unsure which rules a message in flight was written under. An `initialize` refused with UNSUPPORTED_PROTOCOL
 * settled nothing, so the client may send another; the sidecar keeps serving either way.
 */
private initialize(id: string, clientMin: number, clientMax: number, experimental: boolean): void {
  if (this.negotiated) {
    this.emit({ type: "error", id, code: "BAD_REQUEST", message: `initialize was already answered on this connection (protocol ${this.negotiated.protocol}); a connection negotiates once.` });
    return;
  }
  const protocol = Math.min(clientMax, PROTOCOL_MAX);
  if (protocol < Math.max(clientMin, PROTOCOL_MIN)) {
    this.unsupportedProtocol = `No common protocol version: the client speaks ${clientMin} to ${clientMax}, this sidecar speaks ${PROTOCOL_MIN} to ${PROTOCOL_MAX}.`;
    this.emit({
      type: "error", id, code: "UNSUPPORTED_PROTOCOL",
      message: this.unsupportedProtocol,
    });
    return;
  }
  this.negotiated = { protocol, experimental: experimental ? this.experimentalOffered : [] };
  this.unsupportedProtocol = undefined;
  this.emit({ type: "initialized", id, protocol, capabilities: [...SIDECAR_CAPABILITIES], experimental: [...this.negotiated.experimental] });
}

/**
 * The gate every experimental feature's handler calls first: true when this connection enabled `name` (it sent
 * `initialize` with `experimental: true` and this sidecar offers `name`). Otherwise it answers `id` with
 * EXPERIMENTAL_DISABLED and returns false, and the handler does nothing.
 */
requireExperimental(name: string, id?: string): boolean {
  if (this.negotiated?.experimental.includes(name)) return true;
  const message = this.experimentalOffered.includes(name)
    ? `${name} is experimental: send initialize with experimental: true before using it.`
    : `${name} is not an experimental feature this sidecar offers.`;
  this.emit({ type: "error", ...(id ? { id } : {}), code: "EXPERIMENTAL_DISABLED", message });
  return false;
}

/** Sign-ins in progress, by request id (provider.cancel stops one). */
private signIns = new Map<string, { cancel(): void }>();

/** Model-list fetches in flight, by request id: a new list, provider.cancel or shutdown stops them. */
private modelLists = new Map<string, AbortController>();

private async modelsList(id: string): Promise<void> {
  // Only the newest list matters: the picker that asked for an older one is gone.
  for (const older of this.modelLists.values()) older.abort();
  const controller = new AbortController();
  this.modelLists.set(id, controller);
  try {
    const catalog = await buildCatalog(this.app.getConfig(), { signal: controller.signal });
    if (!controller.signal.aborted) this.emit({ type: "models.catalog", id, ...catalog });
  } catch (err) {
    if (!controller.signal.aborted) this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) });
  } finally {
    if (this.modelLists.get(id) === controller) this.modelLists.delete(id);
  }
}

/** Switching models between turns is the operator's choice; during a turn it is refused like any command. */
private modelSelect(id: string, provider: string, model: string): void {
  if (this.rejectBusy(id)) return;
  const r = selectModel(this.app.getAgent(), this.app.getConfig(), { provider, model });
  if (!r.ok && provider === "appliance") clearLocalEndpointSetupAfterSelectionFailure();
  this.emit({ type: "model.result", id, success: r.ok, message: r.message });
  if (r.ok) this.emitSessionState();
}

private async providerConnect(id: string, provider: string, method: string, key?: string, endpoint?: string): Promise<void> {
  const result = (success: boolean, message: string) =>
    this.emit({ type: "provider.result", id, provider: provider, success, message: message });
  try {
    if (provider === "appliance" && method === "local-endpoint") {
      if (!endpoint) {
        result(false, "An endpoint URL is required.");
        return;
      }
      const prepared = await prepareLocalEndpoint(this.app.getConfig(), endpoint, key ?? "", id);
      if (!prepared.cancelled) result(prepared.ok, prepared.message);
      return;
    }
    if (method === "api-key") {
      const r = await connectWithKey(this.app.getConfig(), provider, key ?? "");
      result(r.ok, r.message);
      return;
    }
    if (endpoint !== undefined) {
      result(false, "Endpoint URLs are only accepted for local endpoint setup.");
      return;
    }
    const signIn = await startSignIn(this.app.getConfig(), provider, method);
    this.signIns.set(id, signIn);
    this.emit({
      type: "provider.auth",
      id,
      provider,
      url: signIn.prompt.url,
      ...(signIn.prompt.userCode ? { user_code: signIn.prompt.userCode } : {}),
      instructions: signIn.prompt.instructions,
    });
    const r = await signIn.done;
    this.signIns.delete(id);
    result(r.ok, r.message);
  } catch (err) {
    this.signIns.delete(id);
    result(false, String((err as Error).message ?? err));
  }
}

