import { test } from "node:test";
import * as assert from "node:assert/strict";
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import { MAX_CLIENT_FIELD, MAX_PASTE, MAX_PROTOCOL_NUMBER, MAX_SLASH_OUTPUT, MAX_SUMMARY, MAX_TEXT_FIELD, PROTOCOL_MAX, PROTOCOL_MIN, PROTOCOL_VERSION, SIDECAR_CAPABILITIES } from "../src/protocol.js";
import { schemaFile } from "../scripts/gen_protocol_samples.mjs";
import { loadRecording } from "./helpers/wire_fixture.js";
import type { Schema } from "./helpers/json_schema.js";

// docs/PROTOCOL.md is the reference a client author reads. Its tables are checked against the schema and the code, so
// a message, error code or capability cannot be added, removed or change its required fields without the page.
const doc = fs.readFileSync(fileURLToPath(new URL("../../docs/PROTOCOL.md", import.meta.url)), "utf8");
const schema: Schema = JSON.parse(fs.readFileSync(schemaFile(PROTOCOL_VERSION), "utf8"));

/** The rows of the table under `## <heading>`: the first cell's name (written as code), and the other cells. */
function table(heading: string): Array<{ name: string; cells: string[] }> {
  const start = doc.indexOf(`\n## ${heading}\n`);
  assert.ok(start >= 0, `docs/PROTOCOL.md has a "## ${heading}" section`);
  const end = doc.indexOf("\n## ", start + 1);
  const rows = doc.slice(start, end < 0 ? undefined : end).split("\n").filter((line) => line.startsWith("| `"));
  return rows.map((row) => {
    const [first, ...cells] = row.slice(1, -1).split(" | ").map((cell) => cell.trim());
    const name = /^`([^`]+)`$/.exec(first)?.[1];
    assert.ok(name, `the first cell is one name written as code: ${row}`);
    return { name, cells };
  });
}

const codeNames = (cell: string): string[] => [...cell.matchAll(/`([^`]+)`/g)].map((match) => match[1]);

for (const [heading, def] of [["Commands", "SidecarCommand"], ["Events", "SidecarEvent"]] as const) {
  test(`the ${heading} table lists exactly the schema's message types, each with its required fields`, () => {
    const rows = table(heading);
    const variants: Schema[] = schema.$defs[def].oneOf;
    assert.deepEqual(rows.map((row) => row.name).sort(), variants.map((variant) => variant.properties.type.const).sort());
    for (const variant of variants) {
      const row = rows.find((candidate) => candidate.name === variant.properties.type.const)!;
      const required = variant.required.filter((field: string) => field !== "v" && field !== "type");
      assert.deepEqual(row.cells[0] === "none" ? [] : codeNames(row.cells[0]), required, `${heading}: required fields of ${row.name}`);
      assert.ok(row.cells[1].length > 20, `${heading}: ${row.name} has a meaning`);
      // Fields a row names after "Optional:" are fields of the message, and not required ones.
      const optional = /\bOptional(?: \([^)]*\))?: (.*)$/.exec(row.cells[1])?.[1];
      for (const field of optional ? codeNames(optional) : []) {
        assert.ok(Object.hasOwn(variant.properties, field) && !required.includes(field), `${heading}: ${row.name} has no optional field ${field}`);
      }
    }
  });
}

test("the error-code and capability tables list exactly what the code defines", () => {
  assert.deepEqual(table("Error codes").map((row) => row.name).sort(), [...schema.$defs.ErrorCode.enum].sort());
  assert.deepEqual(table("Capabilities").map((row) => row.name), [...SIDECAR_CAPABILITIES]);
});

test("the numbers the page states are the constants in the code", () => {
  const grouped = (value: number) => value.toLocaleString("en-US");
  assert.ok(doc.includes(`The protocol is version ${PROTOCOL_VERSION}.`));
  assert.ok(doc.includes(`\`PROTOCOL_VERSION\` (${PROTOCOL_VERSION})`));
  assert.ok(doc.includes(`Today the range is ${PROTOCOL_MIN} to ${PROTOCOL_MAX}.`));
  assert.ok(doc.includes(`protocol/sidecar-v${PROTOCOL_VERSION}.schema.json`));
  assert.ok(doc.includes(`| ${grouped(MAX_TEXT_FIELD)} (\`MAX_TEXT_FIELD\`) |`));
  assert.ok(doc.includes(`| ${grouped(MAX_SLASH_OUTPUT)} (\`MAX_SLASH_OUTPUT\`) |`));
  assert.ok(doc.includes(`| ${grouped(MAX_PASTE)} (\`MAX_PASTE\`) |`));
  assert.ok(doc.includes(`| ${grouped(MAX_SUMMARY)} (\`MAX_SUMMARY\`) |`));
  assert.ok(doc.includes(`of at most ${grouped(MAX_CLIENT_FIELD)} characters and version bounds from 1 to ${grouped(MAX_PROTOCOL_NUMBER)}`));
});

test("the worked example is the recorded session, line for line", () => {
  const marker = "<!-- example: turn -->\n```text\n";
  const start = doc.indexOf(marker);
  assert.ok(start >= 0, "the example block follows its marker");
  const shown = doc.slice(start + marker.length, doc.indexOf("\n```", start + marker.length));
  // The connect step and the prompt step of the recording that test/protocol_wire.test.ts replays.
  const expected = loadRecording("turn").steps.slice(0, 2).flatMap((step) => [
    ...(step.send ? [`C: ${JSON.stringify(step.send)}`] : []),
    ...step.expect.map((event) => `S: ${JSON.stringify(event)}`),
  ]);
  assert.equal(shown, expected.join("\n"), "docs/PROTOCOL.md: replace the example block with the lines of cli/test/fixtures/wire/turn.json (steps 1 and 2)");
});

/**
 * Leak and hang guard: `import "./helpers/leak_guard.js";` at the top of a test file fails the file in teardown, naming
 * every RustCoreBridge or AutonomousAgent not shut down, scripted gateway not closed, child process still running and
 * timer still pending, then releases them so the process can exit instead of hanging the job.
 * Resources it cannot see by itself (a custom server) can be registered with `trackResource`.
 * Timers: ref'd timeouts above the count when the file finished loading (a timer created while the file loads is not
 * counted; node:test's own timers are gone by teardown). The check hook is registered once the file has finished
 * loading, so it runs after the file's own `after` hooks; a file that registers hooks after a top-level `await` can run
 * its hooks after the guard's check, and should then release in the test itself.
 */
import { after } from "node:test";
import childProcess from "node:child_process";
import { RustCoreBridge } from "../../src/tools.js";
import { survivors, trackResource, clearTracked } from "./leak_registry.js";

export { trackResource };

const proto = childProcess.ChildProcess.prototype as any;
const originalSpawn = proto.spawn;
proto.spawn = function (this: childProcess.ChildProcess, ...args: unknown[]) {
  const result = originalSpawn.apply(this, args);
  const command = [String((this as any).spawnfile ?? ""), ...((this as any).spawnargs ?? []).slice(1)].join(" ").slice(0, 120);
  trackResource("child process", `pid ${this.pid} ${command}`, () => this.exitCode === null && this.signalCode === null, () => {
    try { process.kill(-(this.pid as number), "SIGKILL"); } catch { this.kill("SIGKILL"); }
  });
  return result;
};

let baselineTimers = 0;
function activeTimers(): number {
  return process.getActiveResourcesInfo().filter((r) => r === "Timeout").length;
}

export function describeSurvivors(): string[] {
  const lines = survivors().map((s) => `${s.kind}: ${s.name}`);
  for (const bridge of (RustCoreBridge as any).activeBridges as Set<RustCoreBridge>) lines.push(`RustCoreBridge not shut down (workspace ${(bridge as any).workspace}); an AutonomousAgent owns one: call agent.shutdown()`);
  const timers = activeTimers() - baselineTimers;
  if (timers > 0) lines.push(`${timers} timer(s) still pending`);
  return lines;
}

// Registered once the file has finished loading so it runs after the file's own `after` hooks.
queueMicrotask(() => {
  baselineTimers = activeTimers();
  after(async () => {
    let lines = describeSurvivors();
    for (let i = 0; i < 20 && lines.length; i++) {
      await new Promise((r) => setTimeout(r, 100));
      lines = describeSurvivors();
    }
    if (!lines.length) return;
    for (const s of survivors()) await Promise.resolve(s.release()).catch(() => {});
    (RustCoreBridge as any).shutdownAllGlobal();
    clearTracked();
    setTimeout(() => process.stdout.write("", () => process.exit(1)), 5_000).unref();
    throw new Error(`${process.argv[1] ?? "test file"} leaked ${lines.length} resource(s) past the end of the file:\n  ${lines.join("\n  ")}`);
  });
});
/**
 * DH-3 / RD-4: every example under examples/ and the action/ wrapper is exercised, so they stay true to the product.
 * Scripts run through a shim of the real CLI against a scripted gateway; nothing contacts a live service.
 */
import "./helpers/leak_guard.js";
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { startGateway, type Reply } from "./helpers/fixtures.js";
import { OperationSpecError, validateOperationSpec } from "../src/operation_cli.js";

const CLI_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ROOT = path.resolve(CLI_DIR, "..");
const TSX = path.join(CLI_DIR, "node_modules", ".bin", "tsx");
const read = (...p: string[]) => fs.readFileSync(path.join(ROOT, ...p), "utf8");

// ------------------------------------------------------------------ operation spec

test("examples/operation/isolate.json is a valid spec, and the isolation it declares is what allows its concurrency", () => {
  const spec = JSON.parse(read("examples", "operation", "isolate.json"));
  assert.doesNotThrow(() => validateOperationSpec(spec));
  assert.equal(spec.git.isolate, true);
  assert.ok(spec.policy.maxConcurrentUnits > 1);
  assert.ok(spec.policy.executionBudget.cpuMilli >= spec.units.reduce((sum: number, unit: any) => sum + unit.executionResources.cpuMilli, 0));
  assert.ok(spec.policy.executionBudget.memoryBytes >= spec.units.reduce((sum: number, unit: any) => sum + unit.executionResources.memoryBytes, 0));
  const without = { ...spec, git: undefined };
  assert.throws(() => validateOperationSpec(without), (e: Error) => e instanceof OperationSpecError && /git\.isolate/.test(e.message));
});

// ------------------------------------------------------------------ the action

/** The bodies of every `run: |` block in a workflow-style YAML file (the file has no other multi-line constructs we need). */
function runBlocks(yaml: string): string[] {
  const lines = yaml.split("\n");
  const blocks: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const m = /^(\s*)run:\s*\|\s*$/.exec(lines[i]);
    if (!m) continue;
    const indent = m[1].length;
    const body: string[] = [];
    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim() && lines[j].search(/\S/) <= indent) break;
      body.push(lines[j].slice(indent + 2));
    }
    blocks.push(body.join("\n"));
  }
  return blocks;
}

test("action.yml: scripts hold no ${{ }} expressions (inputs arrive as env vars), parse as bash, and no credential is an input", () => {
  const yaml = read("action", "action.yml");
  const blocks = runBlocks(yaml);
  assert.equal(blocks.length, 2);
  for (const block of blocks) {
    assert.equal(block.includes("${{"), false, "an expression inside a run script would let an input be interpreted as shell");
    const check = spawnSync("bash", ["-n"], { input: block, encoding: "utf8" });
    assert.equal(check.status, 0, check.stderr);
  }
  assert.match(yaml, /NEXUS_ACTION_PROMPT: \$\{\{ inputs\.prompt \}\}/);
  assert.doesNotMatch(yaml.split("\nruns:")[0], /^\s{2}(api-key|token|secret|password)[a-z-]*:/im, "credentials are passed through env, not inputs");
  assert.match(yaml, /--json/);
  assert.match(yaml, /exit "\$code"/);
});

// ------------------------------------------------------------------ running the scripts

interface Run { code: number | null; out: string; err: string }

async function runScript(script: string, env: Record<string, string>, gatewayReplies: Reply[], cwd = ROOT, endpointFromEnv = false): Promise<Run & { gatewayRequests: number }> {
  const gateway = await startGateway((n) => gatewayReplies[Math.min(n, gatewayReplies.length) - 1]);
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-example-home-"));
  const shim = path.join(home, "nexus");
  fs.writeFileSync(shim, `#!/bin/sh\nexec "${TSX}" "${path.join(CLI_DIR, "src", "index.ts")}" "$@"\n`, { mode: 0o755 });
  const clean = { ...process.env };
  for (const key of Object.keys(clean)) if (/^(LOCAL_LLM_|LOCAL_HARNESS_|NEXUS_)/.test(key)) delete clean[key];
  // Under `node --test` this variable turns a nested `node --test` (the examples' verifier) into a run of zero tests.
